// Tavily убран намеренно: общий веб-поиск не возвращает конкретные туры с ценой/наличием,
// только тематические страницы. Для экскурсионных/авторских/премиум направлений нет
// бесплатного структурированного API уровня Tourvisor, поэтому здесь — честный handoff:
// инструмент собирает параметры и говорит агенту передать запрос менеджеру на ручной подбор.
const p = $json || {};
const intent = String(p.intent || 'excursion').toLowerCase();

const operatorsByIntent = {
  excursion: 'Дельфин, Tury.ru',
  author:    'Good Time Travel',
  premium:   'Sodis',
  any:       'профильные операторы'
};
const operators = operatorsByIntent[intent] || operatorsByIntent.excursion;

const collected = [
  p.destination ? 'Направление: ' + p.destination : '',
  p.city_from   ? 'Вылет из: ' + p.city_from : '',
  p.dates       ? 'Даты: ' + p.dates : '',
  p.duration    ? 'Длительность: ' + p.duration : '',
  p.adults      ? 'Человек: ' + p.adults : '',
  p.budget      ? 'Бюджет: ' + p.budget : '',
  p.query       ? 'Пожелания: ' + p.query : ''
].filter(Boolean).join('; ');

const text = 'Это ' + intent + '-запрос. По таким направлениям точный тур с ценой и наличием подбирается вручную (профильные операторы: ' + operators + '). '
  + 'Не придумывай конкретные туры и не давай ссылок. Скажи клиенту тепло, что подберёшь варианты под его параметры через менеджера, и вызови escalate с собранными данными. '
  + 'Собранные параметры: ' + (collected || 'не заполнены — добери недостающее перед передачей') + '.';

return [{ json: { results_text: text, count: 0, manual: true } }];
